        dict(role='practice', difficulty='ADVANCED', problem_type='CAUSAL_ANALYSIS',
             prompt='Explique cómo adquiere una bacteria resistencia a un fago mediante CRISPR y por qué esa misma maquinaria pudo adaptarse para editar genes. Distinga la inmunidad que da CRISPR de la que da una vacuna.',
             questions=['¿Cómo se «vacuna» la bacteria?', '¿Qué papel tienen la guía y Cas9?', '¿En qué se parece y en qué se diferencia de una vacuna?'],
             answer=dict(summary='Tras una infección, la bacteria guarda un fragmento del fago como espaciador; ese ARN guía lleva a Cas hasta el ADN del fago en una nueva infección y lo corta; la misma lógica, con una guía diseñada, permite cortar cualquier gen. A diferencia de una vacuna, es una inmunidad hereditaria de la bacteria.',
                sections=[
                  dict(label='Adquirir la inmunidad', points=[dict(text='Cada secuencia espaciadora procede de un fragmento de un bacteriófago que infectó antes a la bacteria o a sus ancestros, y se usa para detectar y destruir el ADN de fagos parecidos; S. thermophilus, tras infecciones sucesivas, adquiere más resistencia al incorporar nuevos espaciadores.', quotes=[Q('en_crispr', 'Each sequence within an individual prokaryotic CRISPR is derived from a DNA fragment of a bacteriophage that had previously infected the prokaryote or one of its ancestors.'), Q('en_crispr', 'In 2005, Barrangou discovered that S thermophilus, after iterative phage infection challenges, develops increased phage resistance due to the incorporation of additional CRISPR spacer sequences.')])]),
                  dict(label='Adaptación a la edición', points=[dict(text='Cas9 usa las secuencias CRISPR como guía para reconocer y abrir el ADN complementario; al sustituir la guía por otra, se corta el gen que se desee en cualquier organismo, y la reparación del corte permite eliminar el gen o introducir mutaciones.', quotes=[Q('en_crispr', 'Cas9 (or "CRISPR-associated protein 9") is an enzyme that uses CRISPR sequences as a guide to recognize and open up specific strands of DNA that are complementary to the CRISPR sequence.'), Q('es_crispr', 'Además de jugar un papel clave en los sistemas de defensa bacterianos, estas secuencias formaron la base de una revolucionaria tecnología de vanguardia conocida como CRISPR/Cas, que es capaz de modificar los genes de cualquier organismo utilizando una familia de enzimas con actividad endonucleasa asociadas a CRISPR conocidas como Cas, tal como la Cas9 del sistema CRISPR/Cas9.')])]),
                  dict(label='Comparación con una vacuna', points=[dict(text='Ambas dan una forma de inmunidad adquirida basada en guardar un registro del invasor; la de CRISPR es hereditaria porque queda en el genoma de la bacteria y de su descendencia, mientras que la vacuna estimula el sistema inmunitario de un individuo, que guarda un registro del microorganismo.', quotes=[Q('en_crispr', 'Hence these sequences play a key role in the antiviral (i.e. anti-phage) defense system of prokaryotes and provide a form of heritable, acquired immunity.'), Q('en_vaccine', 'A vaccine is a biological preparation that provides active acquired immunity to a particular infectious or malignant disease.')])]),
                ],
                mistakes=['Decir que CRISPR es una técnica inventada desde cero.', 'Confundir la inmunidad bacteriana con anticuerpos.'])),
        dict(role='practice', difficulty='EXAM_LEVEL', problem_type='DEVELOPMENT_QUESTION',
             prompt='Desarrolle: tres herramientas de la biotecnología molecular (clonación con plásmidos, PCR y CRISPR-Cas9). Explique el fundamento de cada una, un ejemplo de aplicación y las precauciones éticas o técnicas.',
             answer=dict(summary='La clonación une fragmentos de ADN con enzimas y los replica en un hospedador; la PCR los amplifica por ciclos térmicos; CRISPR-Cas9 los corta con precisión; cada una exige controles técnicos y reflexión ética.',
                sections=[
                  dict(label='Clonación', points=[dict(text='Se obtiene ADN recombinante uniendo, con ligasa, fragmentos cortados con enzimas de restricción a un vector plasmídico, que se replica en un hospedador como E. coli; las bacterias que lo captan se seleccionan con un antibiótico.', quotes=[Q('en_cloning', 'Using a second enzyme, DNA ligase, fragments generated by restriction enzymes could be joined in new combinations, termed recombinant DNA.'), Q('en_plasmid', 'Artificial plasmids are widely used as vectors in molecular cloning, serving to drive the replication of recombinant DNA sequences within host organisms.')])]),
                  dict(label='PCR y CRISPR', points=[dict(text='La PCR amplifica una región de ADN de forma exponencial con cebadores y una polimerasa termoestable, y sirve en diagnóstico, forense y genética; CRISPR-Cas9, adaptado de un sistema inmunitario bacteriano, edita genes de organismos vivos.', quotes=[Q('en_pcr', 'PCR is fundamental to many of the procedures used in genetic testing, research, including analysis of ancient samples of DNA, and identification of infectious agents.'), Q('en_crispr', 'Cas9 enzymes together with CRISPR sequences form the basis of a technology known as CRISPR-Cas9 that can be used to edit genes within living organisms.')])]),
                  dict(label='Precauciones', points=[dict(text='En la PCR hay que evitar la contaminación separando las zonas de trabajo; en la edición genética, la secuencia génica no predice por sí sola el fenotipo completo y se plantean cuestiones éticas, legales y sociales que requieren una regulación adecuada.', quotes=[Q('en_pcr', 'To minimize the chance of contamination, investigators should reserve separate rooms for reagent preparation, the PCR, and analysis of product.'), Q('es_hgp', 'Sin embargo, la secuencia génica por sí sola no permite predecir el fenotipo completo, lo que ha planteado importantes cuestiones éticas, legales y sociales que requieren una regulación adecuada.')])]),
                ],
                criteria=['Explica el fundamento de cada técnica.', 'Da un ejemplo.', 'Menciona precauciones.'])),
